"""Publish requested non-PBMS documentation maintenance with backups and history."""
from pathlib import Path
import json,sqlite3,datetime,shutil,re,subprocess
root=Path(__file__).resolve().parent;src=root.parent;runtime=Path('/opt/openg2p-lab');app=runtime/'registration';brand=runtime/'branding'
plan=json.loads((root/'other-module-guidance.json').read_text())
# Verified consent navigation uses partners, approvals and decisions.
for stage,pattern,purpose,steps in [
 ('Partner consent bindings',r'/partners(?:/|$)','Review the association between a partner and the policy that limits its access.','Open the partner binding and check the partner, policy and applicable scope.\nBefore creating a binding, confirm that the intended partner and policy are correct.\nSave only an authorised change and verify the resulting binding.'),
 ('Consent approvals',r'/approvals(?:/|$)','Review consent-related requests awaiting an authorised decision.','Open the relevant request and inspect its partner, purpose and requested scope.\nCheck the supporting information and the decision controls available to your account.\nRecord an authorised decision only after completing the required checks, then confirm the resulting status.'),
 ('Consent decisions',r'/decisions(?:/|$)','Inspect the consent decisions recorded for a sharing request.','Locate the relevant decision using the available filters.\nRead its outcome, scope and related identifiers.\nUse the linked request or policy to investigate discrepancies without assuming that a past decision grants permanent access.')]:
 plan['guides'].append(dict(slug='nsipa-screen-consent-manager-'+stage.lower().replace(' ','-'),module='consent-manager',stage=stage,audience='all',title=stage,purpose=purpose,steps=steps,requirements='An authorised consent-management account and the correct partner or request reference.',next_step='Confirm the current request, policy and consent state before continuing with the related sharing workflow.',issues='If no record appears, check the selected filters and account permissions. Consent approval does not approve programme enrollment or payment. Ask the service administrator to investigate inconsistent or unavailable records.',scope='local_workflow',visibility='public'))
 plan['routes'].insert(0,dict(module='consent-manager',pattern=pattern,stage=stage))
p=root/'context.js';s=p.read_text();s=re.sub(r' const screenRoutes=.*?;\n',lambda m:' const screenRoutes='+json.dumps(plan['routes'],separators=(',',':'))+';\n',s,count=1);p.write_text(s)
(root/'other-module-guidance.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2))
overviews={
 'platform':('NSIPA service navigation','Choose a service and understand which account and workflow it requires.','Identify the task you need to complete.\nOpen the service that handles that task and sign in if requested.\nUse the help for the destination screen before making a change.'),
 'intake':('Household registration overview','Register a household and correct returned information before review.','Check for an existing household registration.\nComplete household details and member information, then resolve validation errors.\nSubmit the registration and track any reviewer feedback.'),
 'review':('Registration review overview','Review submitted household records and record an independent decision.','Select a registration awaiting review.\nCompare its details and supporting information with the required checks.\nUse the permitted approval or return action and confirm the resulting status.'),
 'register':('Modern social registry overview','Find registry records, review proposed changes and follow their approval status.','Choose the appropriate register or task queue.\nOpen the correct individual, household or change request.\nReview its current and proposed values before using a permitted save or submission action.'),
 'registry':('Social registry administration overview','Maintain the legacy registry’s people, households and membership records.','Choose the appropriate record list and locate the person or household.\nCheck identifiers, relationships and existing memberships before editing.\nSave an authorised correction and inspect the resulting record.'),
 'beneficiary':('Beneficiary portal overview','Use the beneficiary portal to register, apply to programmes and follow recorded outcomes.','Check your profile and registration information.\nOpen the relevant programme, application or benefit.\nRead the detailed status and respond to any requested correction.'),
 'awe':('Approval workflows overview','Review approval requests and the policies that route their tasks.','Choose Requests to inspect pending work or Policies to inspect configured routing.\nCheck the selected request or policy version and your available actions.\nReview evidence before a decision and confirm the recorded outcome.'),
 'portal-admin':('Beneficiary programme administration overview','Administer the programme configuration connected to the beneficiary portal.','Sign in to the administration workspace and open the relevant programme.\nReview programme settings, related applications and configured communications.\nMake only authorised changes and confirm their saved status.'),
 'odk':('Field data collection overview','Prepare collection forms and review the submissions received for a project.','Open the assigned project and check its form version.\nCollect only the information required by the approved form.\nReview received submissions and resolve validation or synchronisation issues through the project workflow.'),
 'geography':('Geographic coverage overview','Interpret record counts and available household locations in their geographic context.','Select the geographic scope and read the count labels.\nCheck coordinate provenance and coverage before comparing areas.\nInspect missing or invalid locations separately from eligibility or payment decisions.'),
 'superset':('Analytics overview','Read dashboards with the correct reporting period, filters and data-refresh context.','Open an authorised dashboard or chart.\nCheck the metric definitions and apply the required filters.\nReview the resulting totals and preserve their context when exporting.'),
 'master-data-ui':('Shared reference data overview','Maintain the shared codes and geographic values used across services.','Find the relevant code list, attribute or geographic area.\nCheck its code, label and dependencies before editing.\nSave an authorised update and verify the resulting reference value.'),
 'partner-management':('Partner management overview','Review partner identity, lifecycle and integration access.','Find the partner before adding another record.\nCheck its organisation details, status and configured access.\nUse the authorised update workflow and confirm the resulting status.'),
 'consent-manager':('Consent management overview','Review partner policy bindings, consent approvals and recorded decisions.','Choose Partner policies, Approvals or Decisions according to your task.\nOpen the correct partner binding or request and check its scope.\nUse the action permitted to your account and verify the recorded result.'),
 'staff-portal':('Staff services overview','Open the services assigned to your staff account.','Confirm that you are signed in with the correct account.\nChoose the service that matches your task.\nIf access is denied or a service is missing, contact the access administrator with the service name and error message.'),
 'iam-staff-ui':('Staff access administration overview','Administer staff identities, application assignments and authorised roles.','Find the existing staff account or application.\nCheck its current status and access assignments.\nSave only an authorised change and verify the resulting account or application configuration.')}
stamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ');backup=runtime/'knowledge-corrections'/('other-modules-'+stamp);backup.mkdir(parents=True,mode=0o700)
db=sqlite3.connect(app/'intake.sqlite');db.row_factory=sqlite3.Row
with sqlite3.connect(backup/'intake.sqlite') as c:db.backup(c)
actor='system:nsipa-module-help-maintenance';note='User-requested non-PBMS context correction and screen coverage; maintenance publication, not independent staff review.';updates=[]
with db:
 for row in db.execute("SELECT * FROM km_articles WHERE published IS NOT NULL AND status='published'").fetchall():
  a=json.loads(row['published'])
  if a['module'] not in overviews or a['stage']!='Service overview':continue
  assert row['draft']==row['published'],'Preserve pending staff edits.'
  title,purpose,steps=overviews[a['module']];a.update(title=title,purpose=purpose,steps=steps,requirements='The account permissions required by this service and the correct task or record reference.',next_step='Open the relevant task screen, review its contextual guidance and confirm the status after any permitted action.',issues='If the destination redirects to sign-in, complete the requested authentication. If a callback error, repeated redirect or access denial remains, report the destination address and error to the administrator. Do not assume that another service has the same permissions.')
  version=row['version']+1;content=json.dumps(a,ensure_ascii=False)
  db.execute('UPDATE km_articles SET draft=?,published=?,version=?,published_version=?,author=?,reviewer=NULL,review_note=?,updated=? WHERE id=?',(content,content,version,version,actor,note,stamp,row['id']))
  db.execute('INSERT INTO km_history(article,version,action,actor,at,content,note) VALUES(?,?,?,?,?,?,?)',(row['id'],version,'maintenance_publication',actor,stamp,content,note));updates.append(dict(slug=row['slug'],**a))
 for a in plan['guides']:
  content=json.dumps({k:v for k,v in a.items() if k!='slug'},ensure_ascii=False)
  cur=db.execute("INSERT INTO km_articles(slug,module,stage,audience,draft,version,status,author,published,published_version,updated,review_note) VALUES(?,?,?,?,?,1,'published',?,?,1,?,?)",(a['slug'],a['module'],a['stage'],a['audience'],content,actor,content,stamp,note))
  db.execute('INSERT INTO km_history(article,version,action,actor,at,content,note) VALUES(?,1,?,?,?,?,?)',(cur.lastrowid,'maintenance_publication',actor,stamp,content,note))
for seed in [src/'knowledge-seed.json',root/'seed.json',app/'knowledge-seed.json']:
 shutil.copy2(seed,backup/(str(len(list(backup.iterdir())))+'-seed.json'));data=json.loads(seed.read_text());replacement={a['slug']:a for a in updates};data['articles']=[replacement.get(a['slug'],a) for a in data['articles']]+plan['guides'];seed.write_text(json.dumps(data,ensure_ascii=False,indent=2))
for source,target in [(root/'context.js',brand/'knowledge-context.js'),(root/'help.js',brand/'knowledge-help.js')]:shutil.copy2(target,backup/target.name);shutil.copy2(source,target)
snippet=Path('/etc/nginx/snippets/iqs-brand.conf');shutil.copy2(snippet,backup/'iqs-brand.conf');snippet.write_text(snippet.read_text().replace('nsipa-20261110','nsipa-all-modules-20261110'))
subprocess.run(['nginx','-t'],check=True);subprocess.run(['systemctl','reload','nginx'],check=True)
(root/'other-module-release.json').write_text(json.dumps({'backup':str(backup),'added':len(plan['guides']),'updated':len(updates),'routes':len(plan['routes'])},indent=2))
print((root/'other-module-release.json').read_text())
